    (function () {
  "use strict";
  var FRAME_NAME = "x-storage";
  var MAX_PENDING_PARENT_MESSAGES = 64;
  var SHARED_SESSION_WRITE_LOCK = "ada:shared-session-write";

  var insideTransaction = false;

  // Reuse the lock only on this synchronous stack, never across an await.
  function withSharedSessionLock(write) {
    if (insideTransaction) return write();
    var started = false;
    var timer;
    function run() {
      started = true;
      insideTransaction = true;
      try { return write(); } finally { insideTransaction = false; }
    }
    try {
      var locks = window.navigator && window.navigator.locks;
      if (!locks) return run();
      var controller = new AbortController();
      timer = setTimeout(function () { controller.abort(); }, 2000);
      return locks.request(SHARED_SESSION_WRITE_LOCK,
        { mode: "exclusive", signal: controller.signal }, function () {
          clearTimeout(timer);
          return run();
        }).catch(function (error) {
          if (started) throw error;
          return run();
        }).finally(function () { clearTimeout(timer); });
    } catch (error) {
      clearTimeout(timer);
      if (started) throw error;
      return run();
    }
  }

  function normalizeOrigin(value) {
    if (!value) return null;
    try {
      var url = new URL(value);
      if (url.origin === "null") return null;
      if (url.protocol !== "http:" && url.protocol !== "https:") return null;
      return url.origin;
    } catch (e) {
      return null;
    }
  }

  // Prefer the referrer-derived parent origin, then lock via TOFU on the first
  // valid parent message. With Referrer-Policy: no-referrer this starts null and
  // locks on first message; outbound messages queue until then.
  var parentOrigin = normalizeOrigin(document.referrer);
  var pendingMessages = [];

  function flushPendingMessages() {
    if (!parentOrigin || !window.parent || window.parent === window) return;
    for (var i = 0; i < pendingMessages.length; i++) {
      window.parent.postMessage(pendingMessages[i], parentOrigin);
    }
    pendingMessages.length = 0;
  }

  function send(type, payload, id) {
    if (!window.parent || window.parent === window) return;
    var message = { name: FRAME_NAME, type: type, payload: payload, id: id };
    if (!parentOrigin) {
      if (pendingMessages.length >= MAX_PENDING_PARENT_MESSAGES) pendingMessages.shift();
      pendingMessages.push(message);
      return;
    }
    window.parent.postMessage(message, parentOrigin);
  }

  var storageArea = null;
  var storageUnavailable = false;
  var configureFallbackReported = false;
  try {
    storageArea = window.localStorage;
  } catch (error) {
    // A Web Storage getter that throws (third-party storage blocked) does so for both
    // areas. Stay up and answer every op ok:false so the parent starts fresh instead
    // of waiting on a handshake that never comes.
    storageUnavailable = true;
    reportStorageError("init", null, error);
  }

  function parseStorageKey(candidate) {
    if (typeof candidate !== "string") return null;
    var trimmed = candidate.trim();
    return trimmed !== "" ? trimmed : null;
  }

  function reportStorageError(operation, key, error) {
    // With no storage area every op fails the same way, and the init report already carries
    // the reason: one report per frame lifetime, not one per hydrated key and per write.
    if (storageUnavailable && operation !== "init") return;
    var detail = error && error.message ? error.message : String(error);
    send("frame.error", { name: FRAME_NAME, error: "storage." + operation + " failed: " + detail, key: key });
  }

  // Only Ada-controlled embedders may read or write credential-bearing (auth-state)
  // values. An approved customer origin may embed the frame, but JS on that origin must
  // not read the bot-origin refresh-token blob, nor plant/clear it. Trust is origin-wide,
  // so use exact Ada runtime origins — never a broad *.ada.support suffix.
  //
  // static.ada.support is shared with uploads. Trusting it depends on every user-controlled
  // path remaining non-scriptable: production CloudFront enforces `default-src 'none'` on
  // images/* and videos/*, and platform-integration SVGs are sanitized server-side. If that
  // invariant changes, revoke this origin or move the compatibility runtime first. Messaging
  // CORS is a separate permission and is not evidence of credential-read authorization.
  var ADA_CREDENTIAL_ORIGINS = [
    "https://messaging-assets.ada.support",
    "https://messaging-assets.ada-dev2.support",
    "https://messaging-assets.net:4900",
    "https://static.ada.support"
  ];

  function isAdaControlledOrigin(origin) {
    if (!origin) return false;
    if (origin === window.location.origin) return true;
    return ADA_CREDENTIAL_ORIGINS.indexOf(origin) !== -1;
  }

  function isCredentialKey(key) {
    // MES-888 messaging auth state (web-storage "messagingAuthState" key). The value
    // is implicitly bound to this bot subdomain, so no per-origin/handle prefix is used.
    return key === "messagingAuthState";
  }

  // Ops beyond the original get/set/remove/configure set, so a parent can tell a frame that
  // supports them from an older one without paying a request timeout to find out. Advertised on
  // both startup messages because either one can be the first the parent sees.
  var SUPPORTED_OPS = ["storage.getMany", "storage.getManyInMode", "storage.compareAndWrite"];

  send("frame.origin.report", { origin: window.location.origin, ops: SUPPORTED_OPS });

  var pendingStorageOperation = null;

  window.addEventListener("message", function (event) {
    if (event.source !== window.parent) return;

    var eventOrigin = normalizeOrigin(event.origin);
    if (!eventOrigin) return;
    if (!parentOrigin) {
      parentOrigin = eventOrigin;
      flushPendingMessages();
    } else if (eventOrigin !== parentOrigin) {
      return;
    }

    var message;
    try {
      message = typeof event.data === "string" ? JSON.parse(event.data) : event.data;
    } catch (e) {
      return;
    }

    if (!message || message.name !== "sdk" || typeof message.type !== "string") return;

    function execute() { return handleStorageMessage(message); }
    var operation = pendingStorageOperation
      ? pendingStorageOperation.then(execute)
      : execute();
    if (operation && typeof operation.then === "function") {
      var settled = Promise.resolve(operation).catch(function (error) {
        reportStorageError(message.type.replace("storage.", ""), null, error);
      });
      pendingStorageOperation = settled;
      settled.then(function () {
        if (pendingStorageOperation === settled) pendingStorageOperation = null;
      });
    }
  });

  function handleStorageMessage(message) {
    var payload = message.payload || {};

    if (message.type === "storage.configure") {
      try {
        storageArea = payload.mode === "session" ? window.sessionStorage : window.localStorage;
      } catch (e) {
        // No known browser rejects sessionStorage alone once localStorage worked above, so
        // this stays on the previous area; the report makes such a browser visible if one
        // appears, since a tab-scoped mode that silently stayed on localStorage is durable.
        // The parent configures twice per mount (on load and on hydrate): report it once.
        if (!configureFallbackReported) {
          configureFallbackReported = true;
          reportStorageError("configure", payload.mode, e);
        }
      }
      return;
    }

    if (message.type === "storage.get") {
      var getKey = parseStorageKey(payload.key);
      var value = null;
      var getOk = false;
      if (getKey && isCredentialKey(getKey) && !isAdaControlledOrigin(parentOrigin)) {
        // Refuse credential reads from non-Ada-controlled embedders.
        send("storage.value", { key: getKey, value: null, ok: false }, message.id);
        return;
      }
      if (getKey) {
        try {
          value = storageArea.getItem(getKey);
          getOk = true;
        } catch (error) {
          reportStorageError("get", getKey, error);
        }
      }
      send("storage.value", { key: getKey, value: value, ok: getOk }, message.id);
      return;
    }

    // Read every key in one handler run to eliminate the inter-task gaps of separate frame
    // round-trips. Web Storage does not guarantee a transaction across agent clusters, so a
    // sibling context can still race these calls; this narrows, but does not close, the no-CAS
    // window. The parent uses this to decide whether a live-agent handoff is open before
    // discarding the identity, and a torn read there ends the conversation.
    if (message.type === "storage.getMany" || message.type === "storage.getManyInMode") {
      var manyKeys = Array.isArray(payload.keys) ? payload.keys : [];
      var entries = [];
      for (var i = 0; i < manyKeys.length; i++) {
        var manyKey = parseStorageKey(manyKeys[i]);
        if (!manyKey) {
          entries.push({ key: null, value: null, ok: false });
          continue;
        }
        if (isCredentialKey(manyKey) && !isAdaControlledOrigin(parentOrigin)) {
          entries.push({ key: manyKey, value: null, ok: false });
          continue;
        }
        try {
          var readArea = storageArea;
          if (message.type === "storage.getManyInMode") {
            if (payload.mode !== "normal" && payload.mode !== "session") {
              entries.push({ key: manyKey, value: null, ok: false });
              continue;
            }
            readArea = payload.mode === "session" ? window.sessionStorage : window.localStorage;
          }
          entries.push({ key: manyKey, value: readArea.getItem(manyKey), ok: true });
        } catch (error) {
          reportStorageError("getMany", manyKey, error);
          entries.push({ key: manyKey, value: null, ok: false });
        }
      }
      send("storage.values", { entries: entries, ok: true }, message.id);
      return;
    }

    // The Web Lock serializes the snapshot recheck and write across participating tabs.
    // A decision in the parent before a postMessage round trip cannot authorize a write.
    if (message.type === "storage.compareAndWrite") {
      var mutationStorageArea = storageArea;
      return withSharedSessionLock(function () {
        var expected = payload.expected;
        var writes = payload.writes;
        var committed = false;
        var failure = "invalid-request";
        var currentKey = null;
        var originals = Object.create(null);
        var changedKeys = [];
        if (expected && writes && typeof expected === "object" && typeof writes === "object" &&
            !Array.isArray(expected) && !Array.isArray(writes)) {
          try {
            var readKeys = Object.keys(expected);
            var writeKeys = Object.keys(writes);
            var valid = readKeys.length > 0 && readKeys.every(function (key) {
              return parseStorageKey(key) === key &&
                (expected[key] === null || typeof expected[key] === "string");
            }) && writeKeys.every(function (key) {
              return parseStorageKey(key) === key &&
                (writes[key] === null || typeof writes[key] === "string");
            });
            if (valid) {
              failure = !isAdaControlledOrigin(parentOrigin) &&
                readKeys.concat(writeKeys).some(isCredentialKey) ? "forbidden" : null;
            }
            var unchanged = !failure && readKeys.every(function (key) {
              currentKey = key;
              return mutationStorageArea.getItem(key) === expected[key];
            });
            if (unchanged) {
              writeKeys.forEach(function (key) {
                currentKey = key;
                originals[key] = mutationStorageArea.getItem(key);
              });
              writeKeys.forEach(function (key) {
                currentKey = key;
                if (writes[key] === null) mutationStorageArea.removeItem(key);
                else mutationStorageArea.setItem(key, writes[key]);
                changedKeys.push(key);
              });
              committed = true;
            }
          } catch (error) {
            failure = "storage-failure";
            while (changedKeys.length > 0) {
              var rollbackKey = changedKeys.pop();
              try {
                if (originals[rollbackKey] === null) mutationStorageArea.removeItem(rollbackKey);
                else mutationStorageArea.setItem(rollbackKey, originals[rollbackKey]);
              } catch (rollbackError) {
                failure = "rollback-failure";
                reportStorageError("compareAndWrite.rollback", rollbackKey, rollbackError);
              }
            }
            reportStorageError("compareAndWrite", currentKey, error);
          }
        }
        var result = { ok: committed };
        if (failure) result.error = failure;
        send("storage.ack", result, message.id);
      });
    }

    if (message.type === "storage.set") {
      var setKey = parseStorageKey(payload.key);
      var setOk = false;
      if (setKey && isCredentialKey(setKey) && !isAdaControlledOrigin(parentOrigin)) {
        // Refuse credential writes from non-Ada-controlled embedders (no planting).
        send("storage.ack", { key: setKey, ok: false }, message.id);
        return;
      }
      if (setKey) {
        try {
          if (payload.value === null || payload.value === undefined) {
            storageArea.removeItem(setKey);
          } else {
            storageArea.setItem(setKey, String(payload.value));
          }
          setOk = true;
        } catch (error) {
          reportStorageError("set", setKey, error);
        }
      }
      send("storage.ack", { key: setKey, ok: setOk }, message.id);
      return;
    }

    if (message.type === "storage.remove") {
      var removeKey = parseStorageKey(payload.key);
      var removeOk = false;
      if (removeKey && isCredentialKey(removeKey) && !isAdaControlledOrigin(parentOrigin)) {
        // Refuse credential clears from non-Ada-controlled embedders (no forced logout).
        send("storage.ack", { key: removeKey, ok: false }, message.id);
        return;
      }
      if (removeKey) {
        try {
          storageArea.removeItem(removeKey);
          removeOk = true;
        } catch (error) {
          reportStorageError("remove", removeKey, error);
        }
      }
      send("storage.ack", { key: removeKey, ok: removeOk }, message.id);
      return;
    }
  }

  send("frame.ready", { name: FRAME_NAME, ops: SUPPORTED_OPS });
})();
